<?php require dirname(__DIR__).'/includes/bootstrap.php';require_role(['ADMIN']);page_start('Nhật ký thao tác');table_start(['Thời gian','Người thực hiện','Hành động','Đối tượng','Chi tiết']);foreach(db_all('SELECT n.*,t.ho_ten FROM nhat_ky n LEFT JOIN tai_khoan t ON t.id=n.nguoi_thao_tac_id ORDER BY n.id DESC LIMIT 300')as$r)echo '<tr><td>'.e($r['thoi_gian']).'</td><td>'.e($r['ho_ten']??'Hệ thống').'</td><td>'.e($r['hanh_dong']).'</td><td>'.e($r['doi_tuong'].' '.$r['ma_doi_tuong']).'</td><td>'.e($r['sau_json']).'</td></tr>';table_end();page_end();
